CREATE TABLE "payment_review_cases" (
	"id" uuid PRIMARY KEY NOT NULL,
	"ride_id" uuid NOT NULL,
	"attempt_id" uuid NOT NULL,
	"source" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"acknowledged_at" timestamp with time zone,
	"acknowledged_by" uuid,
	"reference" text,
	CONSTRAINT "payment_review_ack_complete" CHECK (("payment_review_cases"."acknowledged_at" IS NULL AND "payment_review_cases"."acknowledged_by" IS NULL AND "payment_review_cases"."reference" IS NULL) OR ("payment_review_cases"."acknowledged_at" IS NOT NULL AND "payment_review_cases"."acknowledged_by" IS NOT NULL AND "payment_review_cases"."reference" IS NOT NULL AND "payment_review_cases"."reference" ~ '^[A-Za-z0-9][A-Za-z0-9._:/-]{2,119}$'))
);
