CREATE POLICY "payment_review_read" ON "payment_review_cases" AS PERMISSIVE FOR SELECT TO public USING ((current_setting('rove.actor_role',true)='staff' AND current_setting('rove.actor_mfa',true)='true' AND EXISTS(SELECT 1 FROM public.users u JOIN public.staff_permissions p ON p.staff_id=u.id WHERE u.id=NULLIF(current_setting('rove.actor_id',true),'')::uuid AND u.role='staff' AND u.disabled=false AND p.permission='payments.review')) OR "payment_review_cases"."id"=(NULLIF(current_setting('rove.payment_review_intake',true),'')::jsonb->>'id')::uuid);--> statement-breakpoint
CREATE POLICY "payment_review_intake" ON "payment_review_cases" AS PERMISSIVE FOR INSERT TO public WITH CHECK ("payment_review_cases"."id"=(NULLIF(current_setting('rove.payment_review_intake',true),'')::jsonb->>'id')::uuid AND "payment_review_cases"."ride_id"=(NULLIF(current_setting('rove.payment_review_intake',true),'')::jsonb->>'rideId')::uuid AND "payment_review_cases"."attempt_id"=(NULLIF(current_setting('rove.payment_review_intake',true),'')::jsonb->>'attemptId')::uuid AND "payment_review_cases"."source"=NULLIF(current_setting('rove.payment_review_intake',true),'')::jsonb->>'source' AND "payment_review_cases"."acknowledged_at" IS NULL AND "payment_review_cases"."acknowledged_by" IS NULL AND "payment_review_cases"."reference" IS NULL);--> statement-breakpoint
